// Subtitle translation: the cues of an SRT or WebVTT file go to the local model as keyed batches — the same
// <sN>…</sN> tagging the document translator uses, through the shared KeyedTranslation helper — and only the
// cue text is ever sent. Cue numbers, timestamps and the file headers are regenerated by the subtitle writers,
// so the timing of every cue survives untouched. A cue that never comes back keeps its source text rather
// than being lost.

using Filee.Core.Conversion;
using Filee.Core.Formats;
using Filee.Engines.Subtitles;

namespace Filee.Engines.Translation;

internal static class SubtitleTranslator
{
    /// <summary>Cues sent to the model in one request. Cues are short, so a lost batch costs little and recovery is quick.</summary>
    private const int CuesPerBatch = 30;

    /// <summary>
    /// Reads the subtitles of <paramref name="step"/>, translates their cue text with <paramref name="service"/> and
    /// writes the file back in <c>step.To</c> (SRT or WebVTT).
    /// </summary>
    public static async Task<IReadOnlyList<string>> TranslateAsync(
        ConversionStep step, ITranslationService service, string toLang, string fromLang,
        IProgress<double>? progress, CancellationToken cancellationToken)
    {
        var document = SubtitleReader.Read(step.From, await File.ReadAllBytesAsync(step.InputPath, cancellationToken));
        progress?.Report(0.05);

        var cues = document.Cues;
        for (var first = 0; first < cues.Count; first += CuesPerBatch)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var count = Math.Min(CuesPerBatch, cues.Count - first);
            var texts = new List<string>(count);
            for (var i = 0; i < count; i++)
                texts.Add(cues[first + i].Text);

            var translated = await KeyedTranslation.TranslateAsync(texts, toLang, fromLang, service, cancellationToken);
            for (var i = 0; i < count; i++)
            {
                // If the model never answered a cue, or answered it with nothing, the cue keeps its
                // original text: one untranslated line is better than a lost one.
                var candidate = translated[i] is { } answer ? SubtitleMarkup.Normalize(answer) : cues[first + i].Text;
                if (SubtitleMarkup.PlainText(candidate).Length == 0)
                    candidate = cues[first + i].Text;
                cues[first + i] = cues[first + i] with { Text = candidate };
            }

            progress?.Report(0.05 + 0.85 * (first + count) / cues.Count);
        }

        progress?.Report(0.95);
        var output = step.Output.Allocate(FormatRegistry.FindById(step.To)?.PrimaryExtension ?? step.To);
        if (output is null)
            return [];
        await File.WriteAllBytesAsync(output, SubtitleWriter.Write(document, step.To), cancellationToken);
        progress?.Report(1.0);
        return [output];
    }

}
